"""Production source transforms for KHDN V2.39 governance workflows."""
import base64, gzip

def _replace_once(source, old, new, label):
    if old not in source:
        raise RuntimeError(f"KHDN governance patch cannot find: {label}")
    return source.replace(old, new, 1)

_PAYLOAD=''

def patch_source(source):
    ns={"source":source,"_replace_once":_replace_once}
    code=gzip.decompress(base64.b64decode(_PAYLOAD)).decode("utf-8")
    # Payload is authored as the body of patch_source (4-space indentation).
    exec("if True:\n"+code, ns, ns)
    return ns["source"]
